<?php
require_once __DIR__.'/../includes/bootstrap.php';require_role(['customer','vendor']);$user=signed_in();$isVendor=$user['role']==='vendor';$profile=[];if($isVendor){$st=$pdo->prepare('SELECT business_name,owner_name,phone,address AS business_address FROM vendor_profiles WHERE user_id=?');$st->execute([$user['user_id']]);$profile=$st->fetch()?:[];}
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$name=trim($_POST['full_name']??'');$email=strtolower(trim($_POST['email']??''));$business=trim($_POST['business_name']??'');$phone=trim($_POST['phone']??'');$address=trim($_POST['business_address']??'');if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||($isVendor&&($business===''||$phone===''||$address===''))){flash('Complete the required profile details.');header('Location: profile.php');exit;}try{$pdo->beginTransaction();$st=$pdo->prepare('UPDATE users SET full_name=?,email=? WHERE user_id=?');$st->execute([$name,$email,$user['user_id']]);if($isVendor){$st=$pdo->prepare('INSERT INTO vendor_profiles(user_id,business_name,owner_name,phone,address) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE business_name=VALUES(business_name),owner_name=VALUES(owner_name),phone=VALUES(phone),address=VALUES(address)');$st->execute([$user['user_id'],$business,$name,$phone,$address]);}$pdo->commit();$_SESSION['user']['full_name']=$name;$_SESSION['user']['email']=$email;flash('Profile updated.');header('Location: profile.php');exit;}catch(PDOException $error){if($pdo->inTransaction())$pdo->rollBack();flash('That email is already in use. No changes were saved.');header('Location: profile.php');exit;}}
$pageTitle='Profile settings | Redline Royale';$workspaceType=$isVendor?'vendor':'customer';$workspaceActive=$isVendor?'Business profile':'Profile';include __DIR__.'/../includes/header.php';?><div class="page-kicker">ACCOUNT SETTINGS</div><h1 class="page-heading"><?= $isVendor?'Business profile':'Customer profile'?></h1><form class="panel profile-form" method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><?php if($isVendor):?><label for="business-name">Business name</label><input id="business-name" name="business_name" value="<?=e($profile['business_name']??'')?>" required><?php endif;?><label for="full-name"><?=$isVendor?'Owner name':'Full name'?></label><input id="full-name" name="full_name" value="<?=e($isVendor?($profile['owner_name']??$user['full_name']):$user['full_name'])?>" required><label for="email">Email address</label><input id="email" name="email" type="email" value="<?=e($user['email'])?>" required><?php if($isVendor):?><label for="phone">Phone number</label><input id="phone" name="phone" value="<?=e($profile['phone']??'')?>" required><label for="business-address">Business address</label><textarea id="business-address" name="business_address" required><?=e($profile['business_address']??'')?></textarea><?php endif;?><p><button type="submit">Save profile</button></p></form><?php include __DIR__.'/../includes/footer.php';?>
